_KF = os.environ.get('M87_KEY') or os.path.join(os.path.dirname(os.path.abspath(__file__)), '.m87_key')
if not os.path.exists(_KF):
    raise SystemExit('缺少密钥文件 .m87_key，无法启动')
_key = open(_KF, 'rb').read()
if len(_key) != 48:
    raise SystemExit('密钥文件损坏')
_S, _N = _key[:32], _key[32:]


def _ks(n):
    out = b''
    c = 0
    while len(out) < n:
        out += hashlib.sha256(_S + _N + c.to_bytes(8, 'big')).digest()
        c += 1
    return out[:n]


_c = base64.b85decode(_P)
_src = json.loads(zlib.decompress(bytes(a ^ b for a, b in zip(_c, _ks(len(_c))))))

_mod = types.ModuleType('aeslite')
exec(compile(_src['aeslite'], 'aeslite.py', 'exec'), _mod.__dict__)
sys.modules['aeslite'] = _mod

_g = {'__name__': __name__, '__file__': __file__, '__builtins__': __builtins__}
exec(compile(_src['m87'], 'm87.py', 'exec'), _g)
globals().update(_g)
